<div class="content-body">    <div class="card">        <div class="card-header">            <h5><?php echo $this->lang->line('Expense Transactions') ?></h5>            <div class="heading-elements">                <ul class="list-inline mb-0">                    <li><a data-action="collapse"><i class="ft-minus"></i></a></li>                    <li><a data-action="expand"><i class="ft-maximize"></i></a></li>                    <li><a data-action="close"><i class="ft-x"></i></a></li>                </ul>            </div>        </div>        <div class="card-body">            <form id="filter-form" class="form-inline mb-3">                <div class="form-group mr-2">                    <label for="payer_id" class="mr-2">Account</label>                    <select id="payer_id" class="form-control" name="payer_id">                        <option value="">All</option>                        <?php foreach ($accounts as $acc): ?>                            <option value="<?php echo $acc->payerid ?>"><?php echo $acc->payer ?></option>                        <?php endforeach; ?>                    </select>                </div>                <div class="form-group mr-2">                    <label for="start_date" class="mr-2">From</label>                    <input type="date" id="start_date" class="form-control" name="start_date">                </div>                <div class="form-group mr-2">                    <label for="end_date" class="mr-2">To</label>                    <input type="date" id="end_date" class="form-control" name="end_date">                </div>                <button type="submit" class="btn btn-primary">Filter</button>            </form>            <table id="trans_table" class="table table-striped table-bordered" width="100%">                <thead>                <tr>                    <th>Date</th>                    <th>Account</th>                    <th>Particulars</th>                    <th>Debit</th>                    <th>Credit</th>                    <th>Payer</th>                    <th>Method</th>                    <th>Action</th>                </tr>                </thead>                <tfoot>                <tr>                    <th colspan="3" style="text-align:right">Total:</th>                    <th></th>                    <th></th>                    <th colspan="3"></th>                </tr>                </tfoot>                <tbody></tbody>            </table>        </div>    </div></div><script type="text/javascript">    $(document).ready(function () {        let table = $('#trans_table').DataTable({            "processing": true,            "serverSide": true,            "stateSave": true,            "responsive": true,            <?php datatable_lang(); ?>            "ajax": {                "url": "<?php echo site_url('transactions/translist?type=expense') ?>",                "type": "POST",                "data": function (d) {                    d.payer_id = $('#payer_id').val();                    d.start_date = $('#start_date').val();                    d.end_date = $('#end_date').val();                    d["<?php echo $this->security->get_csrf_token_name(); ?>"] = "<?php echo $this->security->get_csrf_hash(); ?>";                }            },            "columnDefs": [                {                    "targets": [0],                    "orderable": true                }            ],            dom: 'Blfrtip',            buttons: [                {                    extend: 'excelHtml5',                    footer: true,                    exportOptions: {                        columns: [0, 1, 2, 3, 4, 5]                    }                }            ],           "footerCallback": function (row, data, start, end, display) {    var api = this.api();    var intVal = function (i) {        if (typeof i === 'string') {            return parseFloat(i.replace(/[₹,]/g, '').trim()) || 0;        }        return typeof i === 'number' ? i : 0;    };    var debitTotal = api.column(3, { page: 'current' }).data().reduce(function (a, b) {        return intVal(a) + intVal(b);    }, 0);    var creditTotal = api.column(4, { page: 'current' }).data().reduce(function (a, b) {        return intVal(a) + intVal(b);    }, 0);    $(api.column(3).footer()).html('₹ ' + debitTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 }));    $(api.column(4).footer()).html('₹ ' + creditTotal.toLocaleString('en-IN', { minimumFractionDigits: 2 }));}        });        $('#filter-form').on('submit', function (e) {            e.preventDefault();            table.ajax.reload();        });    });</script>